const LEGAL_CONTENT={"termos-e-condicoes":{title:"Termos e Condi\xE7\xF5es",eyebrow:"Documentos",intro:"Estes termos regem o uso do site da Maxxi Sa\xFAde e o agendamento de consultas e exames.",sections:[["Uso do site","O conte\xFAdo deste site tem car\xE1ter informativo e n\xE3o substitui a avalia\xE7\xE3o de um profissional de sa\xFAde. Os agendamentos s\xE3o confirmados pela nossa equipe via WhatsApp ou presencialmente."],["Agendamentos e cancelamentos","Pedimos que cancelamentos sejam comunicados com anteced\xEAncia para liberar o hor\xE1rio a outros pacientes. Exames com preparo exigem seguir as orienta\xE7\xF5es enviadas no agendamento."],["Conv\xEAnios e particulares","A cobertura de conv\xEAnios pode mudar sem aviso pr\xE9vio. Recomendamos confirmar a aceita\xE7\xE3o do seu plano antes do atendimento."],["Resultados de exames","Laudos podem ser retirados na cl\xEDnica ou acessados pelo portal online de resultados, com login e senha entregues no momento do exame."],["Contato","D\xFAvidas sobre estes termos podem ser enviadas pelos nossos canais de atendimento, dispon\xEDveis na p\xE1gina de Contato."]]},"politica-de-cookies-br":{title:"Pol\xEDtica de Cookies",eyebrow:"Privacidade",intro:"Esta pol\xEDtica explica como o site da Maxxi Sa\xFAde utiliza cookies e tecnologias semelhantes.",sections:[["O que s\xE3o cookies","Cookies s\xE3o pequenos arquivos armazenados no seu navegador que ajudam o site a funcionar e a entender como ele \xE9 utilizado."],["Como usamos","Utilizamos cookies necess\xE1rios (para lembrar prefer\xEAncias de navega\xE7\xE3o) e cookies de medi\xE7\xE3o e publicidade, que nos permitem entender o desempenho do site e das nossas campanhas. Os cookies de medi\xE7\xE3o s\xE3o ativados na sua visita e voc\xEA pode recus\xE1-los a qualquer momento pelo aviso exibido na primeira p\xE1gina ou pelas configura\xE7\xF5es do navegador."],["Cookies de terceiros \u2014 Meta (Facebook e Instagram)","Utilizamos o Meta Pixel, da Meta Platforms Ireland Ltd., para medir o resultado dos an\xFAncios veiculados no Facebook e no Instagram e exibir an\xFAncios a quem j\xE1 visitou o site. O Pixel registra p\xE1ginas visitadas e cliques em bot\xF5es \u2014 nunca dados de sa\xFAde, resultados de exames, nome, CPF ou informa\xE7\xF5es que voc\xEA envie pelo WhatsApp. Saiba mais em facebook.com/privacy/policy."],["Gerenciar cookies","O aviso exibido na primeira visita permite recusar os cookies de medi\xE7\xE3o \u2014 a recusa interrompe o envio de dados imediatamente e vale para as pr\xF3ximas visitas. Para rever a escolha, apague os dados do site no seu navegador. Tamb\xE9m \xE9 poss\xEDvel bloquear cookies nas configura\xE7\xF5es do navegador \u2014 algumas funcionalidades podem ser afetadas."],["Seus dados (LGPD)","Tratamos dados pessoais conforme a Lei Geral de Prote\xE7\xE3o de Dados (Lei n\xBA 13.709/2018). Veja a nossa Pol\xEDtica de Privacidade para detalhes sobre finalidades, bases legais e seus direitos."]]},"politica-de-privacidade":{title:"Pol\xEDtica de Privacidade",eyebrow:"Privacidade",intro:"Como a Maxxi Sa\xFAde coleta, usa e protege os seus dados pessoais, em conformidade com a Lei Geral de Prote\xE7\xE3o de Dados (Lei n\xBA 13.709/2018).",sections:[["Quem \xE9 o controlador","Maxxi Sa\xFAde \u2014 Diagn\xF3stico por Imagem e An\xE1lises Cl\xEDnicas, CNPJ 11.503.226/0001-21, Tv. Coronel Tancredo, 45 \u2014 Centro \u2014 Altamira/PA. Respons\xE1vel t\xE9cnico: Dr. An\xEDsio Fernando Chaves, m\xE9dico radiologista, CRM 9422 \xB7 R.Q.E. 6391."],["Quais dados coletamos","No site: dados de navega\xE7\xE3o (p\xE1ginas visitadas, origem do acesso, tipo de dispositivo) por meio de cookies. Quando voc\xEA nos procura: os dados que voc\xEA mesmo envia pelo WhatsApp, telefone ou presencialmente \u2014 nome, contato, conv\xEAnio e o pedido m\xE9dico necess\xE1rio ao agendamento. N\xE3o h\xE1 formul\xE1rio de cadastro nem coleta de dados de sa\xFAde neste site."],["Para que usamos","Para agendar e realizar consultas e exames, entrar em contato sobre o seu atendimento, cumprir obriga\xE7\xF5es legais e sanit\xE1rias de guarda de prontu\xE1rios e laudos, e medir a audi\xEAncia do site e o resultado das nossas campanhas de an\xFAncios, o que voc\xEA pode recusar a qualquer momento."],["Bases legais","Execu\xE7\xE3o de contrato e procedimentos preliminares (agendamentos), tutela da sa\xFAde por profissionais de sa\xFAde (atendimento cl\xEDnico), cumprimento de obriga\xE7\xE3o legal (guarda de registros) e leg\xEDtimo interesse em divulgar e medir nossos servi\xE7os (cookies de medi\xE7\xE3o e publicidade), sempre com op\xE7\xE3o de recusa."],["Publicidade e Meta Pixel","Anunciamos no Facebook e no Instagram. O Meta Pixel registra visitas e cliques neste site para medir o desempenho dos an\xFAncios e formar p\xFAblicos. N\xE3o enviamos \xE0 Meta \u2014 nem a nenhum outro parceiro de publicidade \u2014 dados de sa\xFAde, exames, laudos, diagn\xF3sticos ou qualquer informa\xE7\xE3o sens\xEDvel. Voc\xEA pode recusar esses cookies sem preju\xEDzo ao atendimento."],["Com quem compartilhamos","Com operadoras de planos de sa\xFAde para autoriza\xE7\xE3o e faturamento do seu atendimento, com m\xE9dicos e laborat\xF3rios parceiros envolvidos na emiss\xE3o do seu laudo, com autoridades quando exigido por lei, e com provedores de tecnologia que hospedam o site e medem an\xFAncios, nos limites descritos acima."],["Por quanto tempo guardamos","Prontu\xE1rios, laudos e imagens s\xE3o mantidos pelos prazos exigidos pela legisla\xE7\xE3o e pelas normas do Conselho Federal de Medicina. Dados de navega\xE7\xE3o s\xE3o mantidos pelo per\xEDodo de medi\xE7\xE3o das campanhas e depois descartados ou anonimizados."],["Seus direitos","Voc\xEA pode solicitar confirma\xE7\xE3o de tratamento, acesso, corre\xE7\xE3o, anonimiza\xE7\xE3o, portabilidade, informa\xE7\xE3o sobre compartilhamentos e revoga\xE7\xE3o de consentimento. Basta falar com a cl\xEDnica pelos canais da p\xE1gina de Contato, presencialmente ou pelo WhatsApp da Recep\xE7\xE3o (93) 99180-1155."],["Seguran\xE7a","Adotamos medidas t\xE9cnicas e administrativas para proteger seus dados contra acessos n\xE3o autorizados, perda ou divulga\xE7\xE3o indevida. O acesso a laudos e imagens \xE9 feito por login e senha individuais, entregues no momento do exame."],["Menores de idade","O atendimento de crian\xE7as e adolescentes \xE9 feito na presen\xE7a e com o consentimento dos pais ou respons\xE1veis legais."],["Altera\xE7\xF5es","Esta pol\xEDtica pode ser atualizada. A vers\xE3o vigente estar\xE1 sempre dispon\xEDvel nesta p\xE1gina."]]}};function LegalPage(){const e=LEGAL_CONTENT[window.LEGAL_KEY]||{title:"Documento",eyebrow:"Documentos",intro:"",sections:[]};return React.createElement(PageShell,{active:""},React.createElement("div",{"data-screen-label":e.title},React.createElement("section",{style:{padding:"80px 0 32px",background:"linear-gradient(180deg, var(--ms-blue-50) 0%, transparent 100%)"}},React.createElement("div",{className:"container",style:{maxWidth:760}},React.createElement(Eyebrow,{color:"blue"},e.eyebrow),React.createElement("h1",{style:{fontSize:48,fontWeight:900,color:"var(--fg-strong)",letterSpacing:"-0.03em",lineHeight:1.08,margin:"8px 0 16px"}},e.title),e.intro&&React.createElement("p",{style:{fontSize:18,color:"var(--fg-default)",lineHeight:1.55,margin:0}},e.intro))),React.createElement("section",{className:"section-pad-sm"},React.createElement("div",{className:"container",style:{maxWidth:760}},e.sections.map(([o,a],s)=>React.createElement("div",{key:s,style:{marginBottom:28}},React.createElement("h2",{style:{fontSize:22,fontWeight:800,color:"var(--fg-strong)",letterSpacing:"-0.01em",margin:"0 0 8px"}},o),React.createElement("p",{style:{fontSize:16,color:"var(--fg-default)",lineHeight:1.7,margin:0}},a))),React.createElement("p",{style:{fontSize:13,color:"var(--fg-muted)",marginTop:40}},"\xDAltima atualiza\xE7\xE3o: ",new Date().getFullYear(),".")))),React.createElement(TweaksPanel,null))}renderPage(React.createElement(LegalPage,null));
